import BaseComponent from "sap/ui/core/UIComponent";
import ODataModel from "sap/ui/model/odata/v4/ODataModel";
import JSONModel from "sap/ui/model/json/JSONModel";
import type MobileRouter from "sap/m/routing/Router";
import MessageBox from "sap/m/MessageBox";
import MessageToast from "sap/m/MessageToast";
import type ResourceModel from "sap/ui/model/resource/ResourceModel";
import type ResourceBundle from "sap/base/i18n/ResourceBundle";
import { createDeviceModel } from "./model/models";
import { createPwaModel, isIos, isStandalone } from "./util/pwa";
import CartModel from "./model/CartModel";
import { AuthenticationService } from "./auth/AuthenticationService";
import { AuthenticatedProviderFactory } from "./auth/providers/AuthenticatedProviderFactory";
import { XsuaaAuthHelper } from "./auth/providers/XsuaaAuthHelper";
import { SessionStorage } from "./auth/storage/SessionStorage";
import Environment from "./util/Environment";
import { isAuthenticationError, isAuthorizationError, isBackendUnavailableError, isSessionExpiredError } from "./util/http";
import { getBackendErrorMessage } from "./util/feedback";
import StoreService from "./service/StoreService";
import OrderPushService from "./service/OrderPushService";
import OrderWatcher from "./service/OrderWatcher";
import type { WatchedOrder } from "./service/OrderWatcher";
import { createNotificationModel, showBrowserNotification } from "./util/notifications";
import { pushSupported, registerServiceWorker } from "./util/push";
import { playOrderChime } from "./util/sound";
import { buildHowToBuySteps } from "./model/howToBuy";
import { currentUrl, detectInAppBrowser, externalBrowserUrl, restoreForwardedRoute } from "./util/inAppBrowser";
import type { InAppBrowserInfo } from "./util/inAppBrowser";

const ADMIN_ROUTE = "admin";
const LOGIN_ROUTE = "login";

/**
 * @namespace apps.dflc.benditalook
 */
export default class Component extends BaseComponent {

    public static metadata = {
        manifest: "json",
        interfaces: [
            "sap.ui.core.IAsyncContentCreation"
        ]
    };

    private sessionExpiredShown = false;

    private unexpectedErrorShown = false;

    private backendUnavailableShown = false;

    private watcherListenerAttached = false;

    public init(): void {
        super.init();

        void registerServiceWorker();
        void this.start();
    }

    private async start(): Promise<void> {
        restoreForwardedRoute();

        const inAppBrowser = detectInAppBrowser();

        if (inAppBrowser) {
            this.showOpenInBrowser(inAppBrowser);
            return;
        }

        await this.loadRuntimeConfig();

        AuthenticationService.initialize(AuthenticatedProviderFactory.create());
        AuthenticationService.onSessionExpired(() => this.handleSessionExpired());
        AuthenticationService.onAuthError((message) => this.handleAuthError(message));
        AuthenticationService.onAuthChanged(() => void this.syncOrderWatcher());

        this.registerGlobalErrorHandlers();

        this.setModel(createDeviceModel(), "device");
        this.setModel(createPwaModel(), "pwa");
        this.setModel(createNotificationModel(), "notify");
        this.setModel(new CartModel(), "cart");
        this.setModel(new JSONModel({}), "store");
        this.setModel(new JSONModel({ name: "", email: "", busy: false, subscribed: false }), "newsletter");
        this.setModel(this.createHowToBuyModel(), "howToBuy");
        this.setModel(this.createODataModel(XsuaaAuthHelper.getConfig().catalogService), "catalog");
        this.setModel(this.createOrderPushModel(), "orderPush");

        void this.refreshStoreInfo();
        void this.syncOrderWatcher();
        void this.syncOrderPush();

        const router = this.getRouter() as MobileRouter;

        router.getTargetHandler().setCloseDialogs(false);
        router.initialize();

        await this.completeLoginRedirect();
    }

    // Dentro de apps (Instagram etc.) só a tela de "abrir no navegador", sem modelos OData nem pedido de rede
    // (o backend indisponível cairia por cima da tela); o router não inicia para preservar o hash atual.
    private showOpenInBrowser(info: InAppBrowserInfo): void {
        this.setModel(new JSONModel({ ...info, externalUrl: externalBrowserUrl(info.platform), link: currentUrl(), openFailed: false }), "inApp");
        void (this.getRouter() as MobileRouter).getTargets()?.display("openInBrowser");
    }

    /** Liga/desliga o vigia de pedidos conforme a sessão e registra o aviso de novos pedidos. */
    private async syncOrderWatcher(): Promise<void> {
        const watcher = OrderWatcher.getInstance(() => this.ensureAdminModel());

        if (!this.watcherListenerAttached) {
            watcher.onOrders((orders) => this.alertNewOrders(orders));
            this.watcherListenerAttached = true;
        }

        await watcher.sync();
    }

    /** Reenvia os pedidos do aparelho ao servidor e atualiza o card de avisos; falha em silêncio. */
    public async syncOrderPush(): Promise<void> {
        const enabled = await new OrderPushService(this.getModel("catalog") as ODataModel).sync().catch(() => false);

        (this.getModel("orderPush") as JSONModel).setProperty("/enabled", enabled);
    }

    /** Avisa o administrador: som, notificação do navegador e aviso interno na tela. */
    private alertNewOrders(orders: WatchedOrder[]): void {
        const first = orders[0];
        const count = orders.length;
        const title = count > 1 ? this.getText("orderAlertTitlePlural", [String(count)]) : this.getText("orderAlertTitle", [String(first.Number)]);
        const body = count > 1
            ? this.getText("orderAlertBodyPlural", [String(count)])
            : this.getText("orderAlertBody", [String(first.Number), first.CustomerName ?? ""]);

        playOrderChime();
        showBrowserNotification(title, body, `order-${first.ID}`);
        MessageToast.show(count > 1 ? title : body);

        window.dispatchEvent(new CustomEvent("bl-order-alert", { detail: { orders, title, body } }));
    }

    public async ensureAdminModel(): Promise<ODataModel | null> {
        if (!await AuthenticationService.isAuthenticated()) {
            return null;
        }

        const accessToken = AuthenticationService.getSession()?.accessToken ?? "";
        const current = this.getModel() as ODataModel | undefined;

        const authorization = this.authorizationHeader(accessToken);

        if (current && current.getHttpHeaders().Authorization === authorization) {
            return current;
        }

        if (current && authorization && this.updateAuthorization(current, authorization)) {
            return current;
        }

        const model = this.createODataModel(XsuaaAuthHelper.getConfig().adminService, accessToken);
        this.setModel(model);
        current?.destroy();

        return model;
    }

    public async refreshStoreInfo(): Promise<void> {
        try {
            const catalogModel = this.getModel("catalog") as ODataModel;
            const storeInfo = await new StoreService(catalogModel).storeInfo();
            (this.getModel("store") as JSONModel).setData(storeInfo);
        } catch (error) {
            if (isBackendUnavailableError(error)) {
                this.notifyBackendUnavailable();
            }
        }
    }

    public notifyBackendUnavailable(): void {
        if (this.backendUnavailableShown) {
            return;
        }

        this.backendUnavailableShown = true;

        const retry = this.getText("retry");

        MessageBox.error(this.getText("backendUnavailable"), {
            actions: [retry, MessageBox.Action.CLOSE],
            emphasizedAction: retry,
            onClose: (action: string | null) => {
                this.backendUnavailableShown = false;

                if (action === retry) {
                    window.location.reload();
                }
            }
        });
    }

    public handleUnexpectedError(reason: unknown): void {
        if (!reason || isSessionExpiredError(reason) || isBackendUnavailableError(reason) || this.unexpectedErrorShown) {
            return;
        }

        this.unexpectedErrorShown = true;

        const detail = getBackendErrorMessage(reason, (text) => this.getText(text));
        const message = this.getText("unexpectedError");

        MessageBox.error(detail ? `${message}\n\n${detail}` : message, {
            onClose: () => {
                this.unexpectedErrorShown = false;
            }
        });
    }

    private async loadRuntimeConfig(): Promise<void> {
        try {
            await XsuaaAuthHelper.loadRuntimeConfig();
        } catch (error) {
            console.error(error);
        }

        if (Environment.isLocal()) {
            XsuaaAuthHelper.setLocalOverrides();
            delete XsuaaAuthHelper.getConfig().auth;
        }
    }

    private async completeLoginRedirect(): Promise<void> {
        if (!new URLSearchParams(window.location.search).has("code")) {
            return;
        }

        if (await AuthenticationService.isAuthenticated()) {
            this.getRouter().navTo(ADMIN_ROUTE, {}, true);
        }
    }

    private createODataModel(serviceUrl: string, accessToken = ""): ODataModel {
        const model = new ODataModel({
            serviceUrl,
            httpHeaders: accessToken ? { Authorization: this.authorizationHeader(accessToken) } : {},
            operationMode: "Server",
            autoExpandSelect: true,
            earlyRequests: true
        });

        model.attachSessionTimeout(() => AuthenticationService.notifySessionExpired());
        model.getMetaModel().requestObject("/").catch((error: unknown) => {
            if (accessToken && isAuthenticationError(error)) {
                AuthenticationService.notifySessionExpired();
            } else if (!isAuthorizationError(error)) {
                this.notifyBackendUnavailable();
            }
        });

        return model;
    }

    // Troca só o token do modelo existente, preservando rascunhos abertos; false faz o chamador recriar o modelo.
    private updateAuthorization(model: ODataModel, authorization: string): boolean {
        try {
            model.changeHttpHeaders({ Authorization: authorization });

            return true;
        } catch {
            return false;
        }
    }

    private authorizationHeader(accessToken: string): string | undefined {
        return accessToken ? `Bearer ${accessToken}` : undefined;
    }

    private registerGlobalErrorHandlers(): void {
        window.addEventListener("unhandledrejection", (event) => {
            event.preventDefault();
            this.handleUnexpectedError(event.reason);
        });

        window.addEventListener("error", (event) => this.handleUnexpectedError(event.error));
    }

    private handleSessionExpired(): void {
        if (this.sessionExpiredShown) {
            return;
        }

        this.sessionExpiredShown = true;
        SessionStorage.clear();

        MessageBox.warning(this.getText("sessionExpiredMessage"), {
            title: this.getText("sessionExpiredTitle"),
            onClose: () => {
                this.sessionExpiredShown = false;
                this.getRouter().navTo(LOGIN_ROUTE);
            }
        });
    }

    private handleAuthError(message: string): void {
        MessageBox.error(this.getText("authError", [message]), {
            onClose: () => {
                AuthenticationService.clearAuthError();
                this.getRouter().navTo(LOGIN_ROUTE);
            }
        });
    }

    private getText(key: string, parameters?: string[]): string {
        const bundle = (this.getModel("i18n") as ResourceModel).getResourceBundle() as ResourceBundle;
        return bundle.getText(key, parameters) ?? key;
    }

    /** Passos do tutorial "como comprar", compartilhados entre o diálogo e a página de ajuda. */
    private createHowToBuyModel(): JSONModel {
        return new JSONModel({ steps: buildHowToBuySteps((key) => this.getText(key)) });
    }

    /** Estado do card "Avisos do pedido": `enabled` começa com a flag local e é confirmado pelo sync. */
    private createOrderPushModel(): JSONModel {
        const service = new OrderPushService(this.getModel("catalog") as ODataModel);

        return new JSONModel({
            supported: pushSupported(),
            enabled: service.isEnabled(),
            needsInstall: isIos() && !isStandalone(),
            busy: false
        });
    }

}
